function canonicalSourceText(value){const s=String(value??'').trim();if(!s)return s;if(en[s]!==undefined)return s;return reverseSourceMap.get(s)||s;}
function translateBillingServiceText(s){const m=s.match(/^Bill (.+) generated for (\d{6}) - Amount INR ([0-9,.]+)$/);if(!m)return null;const p={en:`Bill ${m[1]} generated for ${m[2]} - Amount ₹${m[3]}`,hi:`बिल ${m[1]} ${m[2]} के लिए बनाया गया - राशि ₹${m[3]}`,mr:`बिल ${m[1]} ${m[2]} साठी तयार केले - रक्कम ₹${m[3]}`,gu:`બિલ ${m[1]} ${m[2]} માટે બનાવાયું - રકમ ₹${m[3]}`,kn:`${m[2]}ಗಾಗಿ ಬಿಲ್ ${m[1]} ರಚಿಸಲಾಗಿದೆ - ಮೊತ್ತ ₹${m[3]}`,ta:`${m[2]}க்கான பில் ${m[1]} உருவாக்கப்பட்டது - தொகை ₹${m[3]}`};return p[current]||p.en;}
function translateText(key){if(key==null)return '';const s=String(key);const billingService=translateBillingServiceText(s);if(billingService)return billingService;const base=fieldAliases[s]||s;const dict=tr[current]||{};const pageMatch=s.match(/^Show Page (\d+)$/);if(pageMatch)return (dict['Show Page']||'Show Page')+' '+pageMatch[1];if(dict[base]!==undefined)return dict[base];if(en[base]!==undefined&&current==='en')return en[base];if(s.startsWith('Hello, '))return (dict['Hello']||'Hello')+', '+s.slice(7);if(s.startsWith('Edit Role: '))return (dict['Edit Role: ']||'Edit Role: ')+s.slice(11);if(s.startsWith('Payment accepted. Transaction ID '))return (dict['Payment accepted. Transaction ID ']||'Payment accepted. Transaction ID ')+s.slice(36);if(s.startsWith('Record payment of ₹'))return (dict['Record payment of ₹']||'Record payment of ₹')+s.slice(19);return en[base]||base;}
function shouldSkip(el){return !el||['SCRIPT','STYLE','NOSCRIPT','OPTION','TEXTAREA'].includes(el.tagName)||el.closest('[data-i18n-ignore]');}
function translateNodeTree(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let n;while((n=walker.nextNode())){const p=n.parentElement;if(shouldSkip(p))continue;const raw=n.nodeValue||'';const s=raw.trim();if(!s)continue;const detected=canonicalSourceText(s);const source=detected!==s||!sourceTextNodes.has(n)?detected:sourceTextNodes.get(n);if(!sourceTextNodes.has(n)||detected!==s)sourceTextNodes.set(n,source);const translated=translateText(source);if(translated!==source)nodes.push([n,raw,s,translated]);}nodes.forEach(([node,raw,s,t])=>node.nodeValue=raw.replace(s,t));}
function translateAttributes(root){const base=root||document;const selector='[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-ca-i18n],[data-ca-placeholder],[placeholder],[title],[aria-label],[alt]';const elements=[];if(base.matches?.(selector))elements.push(base);base.querySelectorAll?.(selector).forEach(el=>elements.push(el));elements.forEach(el=>{const key=el.getAttribute('data-i18n')||el.getAttribute('data-ca-i18n');if(key)el.textContent=translateText(key);const explicitPlaceholder=el.getAttribute('data-i18n-placeholder')||el.getAttribute('data-ca-placeholder');if(explicitPlaceholder){if(!el.hasAttribute('data-s360-source-placeholder'))el.setAttribute('data-s360-source-placeholder',explicitPlaceholder);el.setAttribute('placeholder',translateText(el.getAttribute('data-s360-source-placeholder')));}else if(el.hasAttribute('placeholder')&&!el.closest('[data-i18n-ignore]')){if(!el.hasAttribute('data-s360-source-placeholder'))el.setAttribute('data-s360-source-placeholder',el.getAttribute('placeholder')||'');el.setAttribute('placeholder',translateText(el.getAttribute('data-s360-source-placeholder')));}const explicitTitle=el.getAttribute('data-i18n-title');if(explicitTitle){if(!el.hasAttribute('data-s360-source-title'))el.setAttribute('data-s360-source-title',explicitTitle);el.setAttribute('title',translateText(el.getAttribute('data-s360-source-title')));}else if(el.hasAttribute('title')&&!el.closest('[data-i18n-ignore]')){if(!el.hasAttribute('data-s360-source-title'))el.setAttribute('data-s360-source-title',el.getAttribute('title')||'');el.setAttribute('title',translateText(el.getAttribute('data-s360-source-title')));}if(el.hasAttribute('aria-label')&&!el.closest('[data-i18n-ignore]')){if(!el.hasAttribute('data-s360-source-aria-label'))el.setAttribute('data-s360-source-aria-label',el.getAttribute('aria-label')||'');el.setAttribute('aria-label',translateText(el.getAttribute('data-s360-source-aria-label')));}if(el.hasAttribute('alt')&&!el.closest('[data-i18n-ignore]')){if(!el.hasAttribute('data-s360-source-alt'))el.setAttribute('data-s360-source-alt',el.getAttribute('alt')||'');el.setAttribute('alt',translateText(el.getAttribute('data-s360-source-alt')));}});const selects=[];if(base.matches?.('select'))selects.push(base);if(base.matches?.('option')){const owner=base.closest('select');if(owner)selects.push(owner);}base.querySelectorAll?.('select').forEach(el=>selects.push(el));selects.forEach(sel=>{if(sel.matches('select#language-select,[data-language-selector]'))return;sel.querySelectorAll('option').forEach(o=>{if(!o.hasAttribute('data-s360-source-option'))o.setAttribute('data-s360-source-option',o.textContent||'');const source=o.getAttribute('data-s360-source-option')||'';const translated=translateText(source);if(o.textContent!==translated)o.textContent=translated;});});}
function cleanGarbage(root){const walker=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT);const nodes=[];let n;while((n=walker.nextNode())){if(shouldSkip(n.parentElement))continue;const s=n.nodeValue||'';if(s.includes('\\n')||s.includes('String.fromCharCode(0xFFFD)'))nodes.push(n);}nodes.forEach(n=>n.nodeValue=(n.nodeValue||'').split('\\n').join(' ').split('String.fromCharCode(0xFFFD)').join(''));}
let observer=null;
let selectorBound=false;
let applyingTranslations=false;
const observerOptions={childList:true,subtree:true,characterData:true};
function apply(){if(observer)observer.disconnect();applyingTranslations=true;try{document.documentElement.lang=languages[current].locale.split('-')[0];document.querySelectorAll('select#language-select,[data-language-selector]').forEach(sel=>{const val=current;sel.innerHTML='';Object.entries(languages).forEach(([code,info])=>{const o=document.createElement('option');o.value=code;o.textContent=info.name;sel.appendChild(o);});sel.value=val;});translateAttributes(document);translateNodeTree(document.body);cleanGarbage(document.body);}finally{applyingTranslations=false;if(observer&&document.body)observer.observe(document.body,observerOptions);}}
function bindLanguageSelectors(){if(selectorBound||!document.body)return;selectorBound=true;document.addEventListener('change',e=>{const sel=e.target?.closest?.('select#language-select,[data-language-selector]');if(sel)setLanguage(sel.value);},true);}
function init(){current=allowed(localStorage.getItem('society360-language')||current);bindLanguageSelectors();apply();if(!observer&&document.body){observer=new MutationObserver(ms=>{if(applyingTranslations)return;observer.disconnect();try{for(const m of ms){if(m.type==='characterData'&&m.target.parentElement){translateNodeTree(m.target.parentElement);cleanGarbage(m.target.parentElement);}m.addedNodes.forEach(x=>{if(x.nodeType===1){translateAttributes(x);translateNodeTree(x);cleanGarbage(x)}})}}finally{if(observer&&document.body)observer.observe(document.body,observerOptions);}});observer.observe(document.body,observerOptions);}}
function setLanguage(code){const next=allowed(code);if(next===current){localStorage.setItem('society360-language',current);apply();return;}current=next;localStorage.setItem('society360-language',current);apply();window.dispatchEvent(new CustomEvent('society360-language-changed',{detail:{language:current}}));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>init(),{once:true});else init();
function ensureToastStyles(){if(document.getElementById('s360-toast-style'))return;const s=document.createElement('style');s.id='s360-toast-style';s.textContent='.s360-toast-wrap{position:fixed;left:50%;top:18px;transform:translateX(-50%);z-index:99999;display:flex;flex-direction:column;gap:10px;pointer-events:none;align-items:center}.s360-toast{min-width:260px;max-width:min(420px,calc(100vw - 36px));padding:12px 14px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;box-shadow:0 14px 40px rgba(15,23,42,.16);font:600 12px Arial,sans-serif;color:#1f2937;opacity:0;transform:translateY(10px);transition:.2s}.s360-toast.show{opacity:1;transform:translateY(0)}.s360-toast.success{border-left:4px solid #16a34a}.s360-toast.error{border-left:4px solid #dc2626}.s360-toast.warning{border-left:4px solid #d97706}.s360-toast.info{border-left:4px solid #2563eb}@media(max-width:600px){.s360-toast-wrap{left:12px;right:12px;top:12px;transform:none}.s360-toast{min-width:0;width:100%}}';document.head.appendChild(s)}
function toast(message,type='info',duration=3200){ensureToastStyles();let wrap=document.querySelector('.s360-toast-wrap');if(!wrap){wrap=document.createElement('div');wrap.className='s360-toast-wrap';wrap.setAttribute('aria-live','polite');document.body.appendChild(wrap)}const el=document.createElement('div');el.className='s360-toast '+type;el.textContent=translateText(message);wrap.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),220)},duration)}
window.Society360Toast={show:toast,success:m=>toast(m,'success'),error:m=>toast(m,'error'),warning:m=>toast(m,'warning'),info:m=>toast(m,'info')};
if(!window.__society360AlertPatched){window.__society360AlertPatched=true;window.alert=function(message){const text=String(message||'').trim().toLowerCase();const failed=/\b(error|failed|failure|invalid|required|could not|cannot|unable|denied|unauthorized|forbidden|not found|not allowed|not permitted|missing|duplicate|already exists|exceed)\b/.test(text);const succeeded=/\b(success|saved|updated|created|generated|registered|uploaded|accepted|recorded|completed|deleted|sent|queued|resolved|changed|added|exported|submitted|approved|reverted|reversed|restored|activated|deactivated|imported|marked as)\b/.test(text);toast(message,failed?'error':succeeded?'success':'info')}}
